window.docContents[24].resolve({"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Tensor-product-of-matrix-algebras/#Chapter3___Exercise3___10___1":{"contents":"Exercise 3.10.1. Show that \\operatorname{Mat}_m(k) \\otimes \\operatorname{Mat}_n(k) \\cong \\operatorname{Mat}_{mn}(k).\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.10. Representations of tensor products\tTensor product of matrix algebras","header":"Tensor product of matrix algebras","id":"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Tensor-product-of-matrix-algebras/#Chapter3___Exercise3___10___1"},"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/Hom-from-projective-cover-computes-Jordan-Holder-multiplicity/#Chapter9___Proposition9___2___3":{"contents":"Proposition 9.2.3. Let N be any finite dimensional A-module. Then one has \\dim \\operatorname{Hom}_A(P_i, N) = [N : M_i], the multiplicity of occurrence on M_i in the Jordan-Hölder series of N.\n\nProof. If N = M_j, the statement is clear. Also, if\n\n0 \\to N_1 \\to N_2 \\to N_3 \\to 0\n\nis an exact sequence of A-modules, then the corresponding sequence\n\n0 \\to \\operatorname{Hom}_A(P_i, N_1) \\to \\operatorname{Hom}_A(P_i, N_2) \\to \\operatorname{Hom}_A(P_i, N_3) \\to 0\n\nis exact, as P_i is projective. This implies the statement. \\square\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.2. Projective covers\tHom from projective cover computes Jordan-Holder multiplicity","header":"Hom from projective cover computes Jordan-Holder multiplicity","id":"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/Hom-from-projective-cover-computes-Jordan-Holder-multiplicity/#Chapter9___Proposition9___2___3"},"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/End-of-proof-of-Lemma-5___13___1-_LPAR_statement-on-missing-page_RPAR_/#Chapter5___Discussion_end_of_Lemma5___13___1_proof":{"contents":"Any two elements in the first row of T must be in different columns of T', so there exists q'_1 \\in Q'_\\lambda which moves all these elements to the first row. So there is p_1 \\in P_\\lambda such that p_1 T and q'_1 T' have the same first row. Now do the same procedure with the second row, finding elements p_2, q'_2 such that p_2 p_1 T and q'_2 q'_1 T' have the same first two rows. Continuing so, we will construct the desired elements p, q'. The lemma is proved. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.13. Proof of the classification theorem for representations of $S_n$\tEnd of proof of Lemma 5.13.1 (statement on missing page)","header":"End of proof of Lemma 5.13.1 (statement on missing page)","id":"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/End-of-proof-of-Lemma-5___13___1-_LPAR_statement-on-missing-page_RPAR_/#Chapter5___Discussion_end_of_Lemma5___13___1_proof"},"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/#chapter-05___section-5-23":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.23. Algebraic representations of $GL(V)$","id":"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/#chapter-05___section-5-23"}});
